import {Test, TestingModule} from '@nestjs/testing';
import {BadRequestException} from '@nestjs/common';
import {DocumentsController} from './documents.controller';
import {DocumentsService} from './documents.service';

// all tests were entirely generated by claude. Comments were added by me.
describe('DocumentsController', () => {
    let controller: DocumentsController;

    // The functions that are called by controller get mocked.
    const serviceMock = {
        uploadFile: jest.fn(),
        getAllDocuments: jest.fn(),
        getJsonForId: jest.fn(),
    };

    // create a multer file as a mock.
    const createFile = (): Express.Multer.File =>
        ({
            originalname: 'test.txt',
            buffer: Buffer.from('HEAD|abc'),
        }) as Express.Multer.File;

    beforeEach(async () => {
        // create the module with the mocked service instead of the correct one
        const module: TestingModule = await Test.createTestingModule({
            controllers: [DocumentsController],
            providers: [{provide: DocumentsService, useValue: serviceMock}],
        }).compile();

        controller = module.get(DocumentsController);
    });

    afterEach(() => {
        jest.resetAllMocks();
    });

    describe('uploadFile', () => {
        it('throws BadRequestException when no file is sent', () => {
            expect(() => controller.uploadFile(undefined)).toThrow(BadRequestException);
        });

        it('does not call the service when no file is sent', () => {
            try {
                controller.uploadFile(undefined);
            } catch {
                // expect error. Service should not have been called because controller validates.
            }
            expect(serviceMock.uploadFile).not.toHaveBeenCalled();
        });

        it('passes the file to the service', () => {
            const file = createFile();
            serviceMock.uploadFile.mockReturnValue([]);

            controller.uploadFile(file);

            expect(serviceMock.uploadFile).toHaveBeenCalledWith(file);
        });

        it('returns the result of the service', () => {
            const result = [{id: '1', isSuccess: true, originalFileName: 'test.txt'}];
            serviceMock.uploadFile.mockReturnValue(result);

            expect(controller.uploadFile(createFile())).toBe(result);
        });
    });

    describe('getAllDocuments', () => {
        it('returns the documents of the service', () => {
            const docs = [{id: '1', isSuccess: true, originalFileName: 'test.txt'}];
            serviceMock.getAllDocuments.mockReturnValue(docs);

            expect(controller.getAllDocuments()).toBe(docs);
        });

        it('returns an empty list when the service has no documents', () => {
            serviceMock.getAllDocuments.mockReturnValue([]);

            expect(controller.getAllDocuments()).toEqual([]);
        });
    });

    describe('getJsonFileById', () => {
        it('passes the id to the service', () => {
            serviceMock.getJsonForId.mockReturnValue({});

            controller.getJsonFileById('abc');

            expect(serviceMock.getJsonForId).toHaveBeenCalledWith('abc');
        });

        it('returns the result of the service', () => {
            const json = {RECID: 'HEAD'};
            serviceMock.getJsonForId.mockReturnValue(json);

            expect(controller.getJsonFileById('abc')).toBe(json);
        });

        it('forwards errors of the service', () => {
            serviceMock.getJsonForId.mockImplementation(() => {
                throw new Error('not found');
            });

            expect(() => controller.getJsonFileById('x')).toThrow('not found');
        });
    });
});